(async()=>{const out={};for(const kind of ['curveCancel','curveHold','setThenRamp','rampThenSet']){const c=new OfflineAudioContext(1,16,8000),s=c.createBufferSource(),g=c.createGain(),b=c.createBuffer(1,16,8000);b.getChannelData(0).fill(1);s.buffer=b;s.connect(g);g.connect(c.destination);const p=g.gain;if(kind.startsWith('curve')){p.setValueCurveAtTime(new Float32Array([0,1,-1,0]),0,12/8000);if(kind==='curveCancel')p.cancelScheduledValues(6/8000);else p.cancelAndHoldAtTime(6/8000)}else{p.setValueAtTime(0,0);if(kind==='setThenRamp'){p.setValueAtTime(.25,8/8000);p.linearRampToValueAtTime(1,8/8000)}else{p.linearRampToValueAtTime(1,8/8000);p.setValueAtTime(.25,8/8000)}}s.start();out[kind]=Array.from((await c.startRendering()).getChannelData(0))}return out})()
